package vn.iotstar;
import vn.iotstar.entity.Category;import vn.iotstar.repository.CategoryRepository;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class ProductApiControllerTest {@Autowired MockMvc mvc;@Autowired CategoryRepository categories;
 @Test void productCrudValidationAndSearch() throws Exception {Category c=new Category();c.setCategoryName("Máy tính");c=categories.save(c);String base="productName=Laptop&quantity=2&unitPrice=1000&description=May+tot&discount=10&status=1&categoryId="+c.getCategoryId();mvc.perform(post("/api/product/addProduct?"+base).contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isCreated()).andExpect(jsonPath("$.body.categoryName").value("Máy tính"));mvc.perform(post("/api/product/addProduct?"+base).contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isConflict());mvc.perform(get("/api/product/search?q=Lap&page=0&size=5")).andExpect(status().isOk()).andExpect(jsonPath("$.body.totalElements").value(1));mvc.perform(put("/api/product/updateProduct?productId=1&productName=Laptop+Pro&quantity=3&unitPrice=1200&description=Moi&discount=0&status=1&categoryId="+c.getCategoryId()).contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isOk());mvc.perform(delete("/api/product/deleteProduct?productId=1")).andExpect(status().isOk());}}
